{"python":"import json, re

page = tables['mmc6.pdf']['page8']
raw_rows = page['rows'] if isinstance(page, dict) else page.rows
records = []
diagnostic = []

def cell_parts(c):
    if isinstance(c, dict):
        return c.get('value',''), c.get('ref') or c.get('id') or '', float(c.get('x0', 0) or 0)
    return str(c), '', 0.0

for yi, rr in enumerate(raw_rows, 1):
    cells = rr.get('cells', rr) if isinstance(rr, dict) else rr
    parts = [cell_parts(c) for c in cells]
    text = ' '.join(v for v,_,_ in parts if v)
    diagnostic.append((yi, text))

    pred_hits = [(v,r,x) for v,r,x in parts if re.search(r'sensitive|resistant', v, re.I)]
    outcome_hits = [(v,r,x) for v,r,x in parts if re.search(r'\b(CR|PR|SD|PD)\b', v)]

    if not pred_hits or not outcome_hits:
        continue

    # Prefer a table prediction cell, not prose containing both words.
    pred = None
    for v,r,x in pred_hits:
        if v.strip().lower() in ('sensitive','resistant'):
            pred = (v.strip(), r, x)
            break
    if pred is None:
        continue

    # Take the outcome token in the tabular region; avoid figure-caption prose.
    outcome = None
    for v,r,x in outcome_hits:
        if v.strip() in ('CR','PR','SD','PD') or re.search(r'SD\s*[><=≥≤]?\s*\d+', v):
            outcome = (v.strip(), r, x)
            break
    if outcome is None:
        continue

    ov, orow, ox = outcome
    pv, prow, px = pred
    label = ov.upper()
    if label in ('CR','PR'):
        truth = 1
    elif label == 'PD':
        truth = 0
    elif label.startswith('SD'):
        # Published clinical-benefit rule: SD must exceed 24 weeks.
        m = re.search(r'(?P<op>[><=≥≤]?)\s*(?P<n>\d+)\s*(?:weeks?|w)?', ov + ' ' + text)
        if m:
            n = int(m.group('n'))
            op = m.group('op')
            truth = int(n > 24 or (op in ('>','≥') and n == 24))
        else:
            continue
    else:
        continue

    left_text = ' '.join(v for v,_,x in parts if x < ox and v)
    rid = re.sub(r'\s+', ' ', left_text).strip()[-80:] or f'row-{yi}'
    records.append({
        'id': rid,
        'score': {'ref': prow, 'map': {'Sensitive': 1, 'Resistant': 0, 'sensitive': 1, 'resistant': 0}},
        'truth': {'ref': orow, 'map': {ov: truth}}
    })

print('Parsed records:', len(records))
for n, t in diagnostic:
    if n >= 8:
        print(n, t[:220])

if len(records) == 29:
    status = 'computed'
    blocked = None
else:
    status = 'blocked'
    blocked = 'Could not identify exactly 29 same-row PDTO prediction and clinical-outcome cells on mmc6.pdf page8; parsed %d records.' % len(records)

CONTRACT = {
    'status': status,
    'fields': {
        'unit': {'value': 'patient_regimen', 'evidence': ['article:p40','article:p45'], 'explanation': 'The evaluation unit is an evaluable treatment; 18 patients contributed 29 treatments.'},
        'platform': {'value': 'organoid', 'evidence': ['article:p30','article:p40'], 'explanation': 'Drug responses were measured in patient-derived tumor organoids.'},
        'readout': {'value': 'size_viability', 'evidence': ['article:p30'], 'explanation': 'Viability was based on mean PDTO size after treatment.'},
        'direction': {'value': 'lower_sensitive', 'evidence': ['article:p30','article:p40'], 'explanation': 'Lower residual viability/AUC denotes greater sensitivity; the figure records the resulting binary sensitive or resistant call.'},
        'threshold_rule': {'value': 'cohort_quantile', 'evidence': ['article:p40'], 'explanation': 'Therapy-specific cutoffs were selected from sensitivity distributions of 56 treatment-naive PDTOs and first-line trial response rates.'},
        'threshold_timing': {'value': 'independent_reference', 'evidence': ['article:p40','article:p45'], 'explanation': 'Cutoffs were developed in a separate treatment-naive reference cohort before testing this independent palliative-treatment cohort.'},
        'patient_mapping': {'value': 'individual_available' if len(records)==29 else 'partial', 'evidence': ['mmc6.pdf/page8'], 'explanation': 'Figure 4B lists treatment-level predictions and clinical outcomes.'},
        'regimen_match': {'value': 'matched', 'evidence': ['article:p40'], 'explanation': 'Each clinical treatment was matched to the corresponding PDTO single-agent or combination-matrix prediction.'},
        'n_units': {'value': 29 if len(records)==29 else len(records), 'evidence': ['article:p40','article:p45'], 'explanation': 'The requested headline denominator is 29 evaluable treatments.'},
        'split': {'value': 'independent_test', 'evidence': ['article:p40','article:p43'], 'explanation': 'The 29-treatment cohort was independent of the 56-PDTO cutoff-development cohort.'}
    },
    'headline': {
        'metric': 'accuracy',
        'reported': 24/29,
        'reported_evidence': ['article:p45'],
        'threshold': 0.5,
        'op': '>',
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': blocked
    },
    'notes': ['Clinical benefit was CR, PR, or SD for more than 24 weeks.', 'The combined 39-treatment cohort is a different analysis and is not used here.']
}
print(json.dumps(CONTRACT, indent=2))"}
